import React, { FC, useCallback, useState } from 'react';
import { isEmpty } from 'lodash-es';
import { ROLES } from '@getvim/platform-consts';
import { MissingInformationContainer } from '../user-management-missing-information-container';
import { UpdateRoleForm } from '../user-management-update-role-form';
import { UpdateRoleFormSuccess } from '../user-management-update-role-form-success';

interface ManagementActionProps {
  onUpdateUserRoles: (roles: string[]) => Promise<boolean>;
}

export const ManagementAction: FC<ManagementActionProps> = ({ onUpdateUserRoles }) => {
  const [isSuccess, setIsSuccess] = useState(false);
  const [roles, setRoles] = useState<string[]>([]);

  const onSubmit = useCallback(async () => {
    if (isEmpty(roles)) return;
    const success = await onUpdateUserRoles(roles);
    setIsSuccess(success);
  }, [onUpdateUserRoles, roles]);

  const onChange = useCallback((values) => setRoles(values), []);

  return (
    <MissingInformationContainer noInformationRequired={isSuccess}>
      {isSuccess ? (
        <UpdateRoleFormSuccess />
      ) : (
        <UpdateRoleForm
          options={ROLES}
          onChange={onChange}
          defaultValues={[]}
          onSubmit={onSubmit}
        />
      )}
    </MissingInformationContainer>
  );
};
